package com.example.campsitelottery

import com.google.firebase.firestore.DocumentSnapshot
import com.google.firebase.firestore.FieldValue
import com.google.firebase.firestore.FirebaseFirestore

/** Where an image in Admin → Images comes from. */
enum class AdminImageKind { CAMPSITE, PROFILE }

/**
 * A user's profile picture as Admin → Images needs it.
 *
 * @property userId the user's document ID.
 * @property name the user's name, possibly blank.
 * @property image the stored picture (Base64 JPEG, see [encodeProfileImage]).
 */
data class ProfileImageEntry(val userId: String, val name: String, val image: String)

/**
 * One image card in Admin → Images.
 *
 * @property kind whether it's a campsite image or a profile picture.
 * @property id the campsite ID or user ID the image is stored on.
 * @property name the campsite's name, or the user's name for a profile picture.
 * @property ownerId who the image belongs to: the campsite owner, or the user themselves.
 * @property ownerLabel [ownerId]'s name when known, otherwise the ID.
 * @property imageUrl the stored image.
 */
data class AdminImageItem(
    val kind: AdminImageKind,
    val id: String,
    val name: String,
    val ownerId: String,
    val ownerLabel: String,
    val imageUrl: String,
) {
    /** Unique across both kinds, since a campsite and a user could share an ID. */
    val key: String get() = "${kind.name}_$id"
}

/** The choices in Admin → Images' Filter menu. */
enum class ImageFilterMode(val label: String) {
    ALL("All Images"),
    CAMPSITES("Campsite Images"),
    PROFILES("Profile Pictures"),
    SORT_CAMPSITE("Sort: Campsite A-Z"),
    SORT_OWNER("Sort: Owner A-Z"),
}

/** Builds, searches and sorts the images shown in Admin → Images. */
object AdminImageList {

    const val UNNAMED_CAMPSITE = "Unnamed Campsite"
    const val UNNAMED_USER = "Unnamed user"
    const val UNKNOWN_OWNER = "Unknown Owner"

    /**
     * Every campsite with an image, followed by every user with a profile picture.
     *
     * @param ownerNames names of campsite owners loaded so far, by user ID.
     */
    fun build(
        campsites: List<Campsite>,
        ownerNames: Map<String, String>,
        profiles: List<ProfileImageEntry>,
    ): List<AdminImageItem> {
        val campsiteImages = campsites
            .filter { !it.imageUrl.isNullOrBlank() }
            .map { site ->
                AdminImageItem(
                    kind = AdminImageKind.CAMPSITE,
                    id = site.campsiteId,
                    name = site.name.ifBlank { UNNAMED_CAMPSITE },
                    ownerId = site.ownerId,
                    ownerLabel = site.ownerId.takeIf { it.isNotBlank() }
                        ?.let { ownerNames[it] ?: it }
                        ?: UNKNOWN_OWNER,
                    imageUrl = site.imageUrl.orEmpty(),
                )
            }
        val profileImages = profiles
            .filter { it.userId.isNotBlank() && it.image.isNotBlank() }
            .map { profile ->
                val name = profile.name.ifBlank { UNNAMED_USER }
                AdminImageItem(
                    kind = AdminImageKind.PROFILE,
                    id = profile.userId,
                    name = name,
                    ownerId = profile.userId,
                    ownerLabel = name,
                    imageUrl = profile.image,
                )
            }
        return campsiteImages + profileImages
    }

    /**
     * The images matching [query] (name, owner or ID, ignoring case, or a campsite image's web address),
     * filtered or sorted by [mode]. Stored image data is never searched.
     */
    fun visible(items: List<AdminImageItem>, query: String, mode: ImageFilterMode): List<AdminImageItem> {
        val ofKind = when (mode) {
            ImageFilterMode.CAMPSITES -> items.filter { it.kind == AdminImageKind.CAMPSITE }
            ImageFilterMode.PROFILES -> items.filter { it.kind == AdminImageKind.PROFILE }
            else -> items
        }
        val q = query.trim()
        val matching = if (q.isEmpty()) ofKind else ofKind.filter { item ->
            item.name.contains(q, ignoreCase = true) ||
                item.ownerLabel.contains(q, ignoreCase = true) ||
                item.ownerId.contains(q, ignoreCase = true) ||
                (item.kind == AdminImageKind.CAMPSITE && isWebAddress(item.imageUrl) &&
                    item.imageUrl.contains(q, ignoreCase = true))
        }
        return when (mode) {
            // Campsite images A-Z, then profile pictures A-Z.
            ImageFilterMode.SORT_CAMPSITE -> matching.sortedWith(compareBy({ it.kind }, { it.name.lowercase() }))
            ImageFilterMode.SORT_OWNER -> matching.sortedBy { it.ownerLabel.lowercase() }
            else -> matching
        }
    }

    private fun isWebAddress(image: String): Boolean =
        image.startsWith("http://", ignoreCase = true) || image.startsWith("https://", ignoreCase = true)
}

/** Loads and removes the images shown in Admin → Images. */
interface AdminImageRepository {

    /** Calls [onUpdate] with every campsite now and after each change. Returns a function that stops listening. */
    fun listenToCampsites(onUpdate: (List<Campsite>) -> Unit, onError: (Exception) -> Unit): () -> Unit

    /** Calls [onUpdate] with every user who has a profile picture now and after each change. Returns a function that stops listening. */
    fun listenToProfileImages(onUpdate: (List<ProfileImageEntry>) -> Unit, onError: (Exception) -> Unit): () -> Unit

    /** Looks up a user's name; [onResult] gets null if it isn't known. */
    fun loadUserName(userId: String, onResult: (String?) -> Unit)

    /** Deletes a campsite's image. */
    fun removeCampsiteImage(campsiteId: String, onSuccess: () -> Unit, onFailure: (Exception) -> Unit)

    /**
     * Deletes a user's profile picture, but only if it's still [expectedImage], so an admin never removes
     * a newer picture they haven't seen. Fails with a message for the admin otherwise.
     */
    fun removeProfileImage(
        userId: String,
        expectedImage: String,
        onSuccess: () -> Unit,
        onFailure: (Exception) -> Unit,
    )
}

/** Messages shown to the admin when removing a profile picture fails. */
object AdminImageMessages {
    const val PROFILE_GONE = "This profile no longer exists."
    const val PICTURE_GONE = "This profile picture was already removed."
    const val PICTURE_CHANGED = "This profile picture has changed. Check the new one before removing it."
}

/** Reads and writes images in the Firestore `campsites` and `users` collections. */
class FirestoreAdminImageRepository(
    private val db: FirebaseFirestore = FirebaseFirestore.getInstance(),
) : AdminImageRepository {

    private val campsites get() = db.collection("campsites")
    private val users get() = db.collection("users")

    override fun listenToCampsites(onUpdate: (List<Campsite>) -> Unit, onError: (Exception) -> Unit): () -> Unit {
        val registration = campsites.addSnapshotListener { snapshot, error ->
            if (error != null) return@addSnapshotListener onError(error)
            onUpdate(
                snapshot?.documents?.mapNotNull { doc ->
                    runCatching { doc.toObject(Campsite::class.java)?.copy(campsiteId = doc.id) }.getOrNull()
                }.orEmpty()
            )
        }
        return { registration.remove() }
    }

    override fun listenToProfileImages(
        onUpdate: (List<ProfileImageEntry>) -> Unit,
        onError: (Exception) -> Unit,
    ): () -> Unit {
        // Only users with a picture, so the pictures of everyone else aren't downloaded.
        val registration = users.whereNotEqualTo("profileImageUrl", null)
            .addSnapshotListener { snapshot, error ->
                if (error != null) return@addSnapshotListener onError(error)
                onUpdate(snapshot?.documents?.mapNotNull(::profileImageEntry).orEmpty())
            }
        return { registration.remove() }
    }

    private fun profileImageEntry(doc: DocumentSnapshot): ProfileImageEntry? = runCatching {
        val image = doc.getString("profileImageUrl")?.takeIf { it.isNotBlank() } ?: return null
        // A name that isn't text shouldn't hide a picture the admin may need to remove.
        ProfileImageEntry(doc.id, runCatching { doc.getString("name") }.getOrNull().orEmpty(), image)
    }.getOrNull()

    override fun loadUserName(userId: String, onResult: (String?) -> Unit) {
        users.document(userId).get()
            .addOnSuccessListener { doc ->
                onResult(runCatching { doc.getString("name") }.getOrNull()?.takeIf { it.isNotBlank() })
            }
    }

    override fun removeCampsiteImage(campsiteId: String, onSuccess: () -> Unit, onFailure: (Exception) -> Unit) {
        campsites.document(campsiteId)
            .update("imageUrl", FieldValue.delete())
            .addOnSuccessListener { onSuccess() }
            .addOnFailureListener(onFailure)
    }

    override fun removeProfileImage(
        userId: String,
        expectedImage: String,
        onSuccess: () -> Unit,
        onFailure: (Exception) -> Unit,
    ) {
        val ref = users.document(userId)
        db.runTransaction { tx ->
            val doc = tx.get(ref)
            check(doc.exists()) { AdminImageMessages.PROFILE_GONE }
            val current = doc.getString("profileImageUrl")
            check(!current.isNullOrBlank()) { AdminImageMessages.PICTURE_GONE }
            check(current == expectedImage) { AdminImageMessages.PICTURE_CHANGED }
            tx.update(ref, "profileImageUrl", FieldValue.delete())
        }
            .addOnSuccessListener { onSuccess() }
            .addOnFailureListener(onFailure)
    }
}

/** An in-memory [AdminImageRepository] for tests. Listeners are told about every change straight away. */
class InMemoryAdminImageRepository(
    campsites: List<Campsite> = emptyList(),
    profiles: List<ProfileImageEntry> = emptyList(),
    private val userNames: Map<String, String> = emptyMap(),
) : AdminImageRepository {

    private val campsites = campsites.associateBy { it.campsiteId }.toMutableMap()
    private val profiles = profiles.associateBy { it.userId }.toMutableMap()
    private val campsiteListeners = mutableListOf<(List<Campsite>) -> Unit>()
    private val profileListeners = mutableListOf<(List<ProfileImageEntry>) -> Unit>()
    private var failure: Exception? = null

    /** The campsites as stored now. */
    fun storedCampsites(): List<Campsite> = campsites.values.toList()

    /** The profile pictures as stored now. */
    fun storedProfiles(): List<ProfileImageEntry> = profiles.values.toList()

    /** Stores or replaces a campsite, as if its owner changed it. */
    fun putCampsite(site: Campsite) {
        campsites[site.campsiteId] = site
        campsiteListeners.toList().forEach { it(storedCampsites()) }
    }

    /** Stores or replaces a profile picture, as if the user changed it. */
    fun putProfile(profile: ProfileImageEntry) {
        profiles[profile.userId] = profile
        notifyProfiles()
    }

    /** Makes the next removal fail with [error]. */
    fun failNextRemovalWith(error: Exception) {
        failure = error
    }

    override fun listenToCampsites(onUpdate: (List<Campsite>) -> Unit, onError: (Exception) -> Unit): () -> Unit {
        campsiteListeners += onUpdate
        onUpdate(storedCampsites())
        return { campsiteListeners -= onUpdate }
    }

    override fun listenToProfileImages(
        onUpdate: (List<ProfileImageEntry>) -> Unit,
        onError: (Exception) -> Unit,
    ): () -> Unit {
        profileListeners += onUpdate
        onUpdate(storedProfiles())
        return { profileListeners -= onUpdate }
    }

    override fun loadUserName(userId: String, onResult: (String?) -> Unit) = onResult(userNames[userId])

    override fun removeCampsiteImage(campsiteId: String, onSuccess: () -> Unit, onFailure: (Exception) -> Unit) {
        takeFailure()?.let { return onFailure(it) }
        val site = campsites[campsiteId] ?: return onFailure(IllegalStateException("This campsite no longer exists."))
        campsites[campsiteId] = site.copy(imageUrl = null)
        campsiteListeners.toList().forEach { it(storedCampsites()) }
        onSuccess()
    }

    override fun removeProfileImage(
        userId: String,
        expectedImage: String,
        onSuccess: () -> Unit,
        onFailure: (Exception) -> Unit,
    ) {
        takeFailure()?.let { return onFailure(it) }
        val profile = profiles[userId] ?: return onFailure(IllegalStateException(AdminImageMessages.PICTURE_GONE))
        if (profile.image != expectedImage) return onFailure(IllegalStateException(AdminImageMessages.PICTURE_CHANGED))
        profiles.remove(userId)
        notifyProfiles()
        onSuccess()
    }

    private fun takeFailure(): Exception? = failure.also { failure = null }

    private fun notifyProfiles() = profileListeners.toList().forEach { it(storedProfiles()) }
}
